import sys

def solve(s: str) -> bool:
    """Return True if brackets in s are balanced ((), [], {}). Ignore other characters."""
    opening = "([{"
    closing = ")]}"
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != match[ch]:
                return False
            stack.pop()
    return not stack

