def solve(tokens):
    """Evaluate reverse Polish notation expression.
    Tokens are strings representing integers or operators + - * /.
    Division truncates toward zero.
    Return integer result.
    """
    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
