def solve(s):
    """Return True if s is a valid IPv4 address.
    Rules:
    - Exactly four decimal numbers separated by dots.
    - Each part contains only digits.
    - No leading zeros unless the part is exactly '0'.
    - Integer value between 0 and 255 inclusive.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # No leading zeros unless the number is zero itself
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True

