def solve(coins, amount):
    # DP for unbounded coin change (minimum number of coins)
    # Initialize dp array where dp[i] is min coins to make i, INF for impossible.
    INF = amount + 1  # any value > possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

