def solve(path):
    # Split path by '/' and process components using a stack.
    # Handles absolute and relative paths robustly.
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            # Ignore empty components and current directory.
            continue
        if p == '..':
            if stack:
                stack.pop()
            else:
                # If relative path and trying to go above start, keep '..'
                # For absolute paths, we stay at root.
                if not path.startswith('/'):
                    stack.append('..')
            continue
        # Normal directory name.
        stack.append(p)
    # Build result: keep leading slash if original was absolute.
    if path.startswith('/'):
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack) if stack else '.'

