def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    if n <= 2:
        return 0
    # is_prime[i] == 1 means i is currently considered prime
    is_prime = bytearray(b'\x01') * n
    is_prime[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            # start marking from p*p, which is the first multiple needing elimination
            start = p * p
            for multiple in range(start, n, p):
                is_prime[multiple] = 0
    # sum of byte values gives count of primes
    return int(sum(is_prime))

