def solve_opt(meetings):
    # brute force optimal using backtracking for small n (<=8)
    from itertools import combinations
    best=0
    n=len(meetings)
    for r in range(n+1):
        for combo in combinations(meetings, r):
            # sort by start
            sel=sorted(combo, key=lambda x:x[0])
            ok=True
            last_end=-float('inf')
            for s,e in sel:
                if s<last_end:
                    ok=False;break
                last_end=e
            if ok:
                best=max(best, r)
    return best

def solve_greedy(meetings):
    # filter start <= end
