def solve(s: str) -> bool:
    """Return True iff *s* is a valid IPv4 address.
    Rules:
    * Exactly four decimal numbers separated by '.'
    * Each number is between 0 and 255 inclusive
    * No leading zeros unless the number is exactly "0"
    * Each part consists only of digits
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p:
            return False
        if not p.isdigit():
            return False
        # no leading zeros unless the part is exactly "0"
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

