def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited
    copies of each coin in *coins*. Return -1 if impossible.
    Handles edge cases such as empty coin list, non‑positive coin values, and
    negative amounts.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Filter out non‑positive coin denominations to avoid infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1  # larger than any feasible answer (max coins = amount when coin=1)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            # If we can reach (x - coin), we can reach x with one more coin
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

