def solve(s):
    """Return True if the string s is a valid IPv4 address.
    An IPv4 address consists of four decimal numbers separated by '.'
    Each number must be between 0 and 255 inclusive, contain no leading zeros
    unless the number itself is zero, and consist only of digits.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # each part must be non‑empty and all digits
        if not p or not p.isdigit():
            return False
        # leading zero check
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

